PRAGMA foreign_keys=ON;
CREATE TABLE app_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE profiles(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,pin_required INTEGER NOT NULL DEFAULT 0 CHECK(pin_required IN(0,1)),save_version INTEGER NOT NULL DEFAULT 1,curriculum_version TEXT NOT NULL,difficulty TEXT NOT NULL DEFAULT 'practice' CHECK(difficulty IN('explore','practice','train','challenge')),coach_mode TEXT NOT NULL DEFAULT 'calm' CHECK(coach_mode IN('silent','calm','competitive')),coach_frequency TEXT NOT NULL DEFAULT 'normal' CHECK(coach_frequency IN('low','normal','high')),ui_prefs_json TEXT NOT NULL DEFAULT '{}',ai_prefs_json TEXT NOT NULL DEFAULT '{}',is_test_profile INTEGER NOT NULL DEFAULT 0 CHECK(is_test_profile IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE pin_credentials(id TEXT PRIMARY KEY,subject_type TEXT NOT NULL CHECK(subject_type IN('site','profile','admin')),subject_id TEXT NOT NULL,salt_b64 TEXT NOT NULL,verifier_b64 TEXT NOT NULL,kdf_name TEXT NOT NULL DEFAULT 'PBKDF2-HMAC-SHA256',kdf_iterations INTEGER NOT NULL,failed_count INTEGER NOT NULL DEFAULT 0,lockout_level INTEGER NOT NULL DEFAULT 0,locked_until TEXT,last_failed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(subject_type,subject_id));
CREATE TABLE auth_sessions(session_hash TEXT PRIMARY KEY,role TEXT NOT NULL CHECK(role IN('site','learner','admin')),profile_id TEXT,created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT,FOREIGN KEY(profile_id) REFERENCES profiles(id));
CREATE INDEX idx_auth_sessions_profile ON auth_sessions(profile_id);CREATE INDEX idx_auth_sessions_expiry ON auth_sessions(expires_at);
CREATE TABLE progress(profile_id TEXT PRIMARY KEY,save_version INTEGER NOT NULL,metrics_version INTEGER NOT NULL DEFAULT 1,curriculum_version TEXT NOT NULL,stage_id TEXT NOT NULL,unlocked_keys_json TEXT NOT NULL DEFAULT '[]',current_lesson_id TEXT,resume_json TEXT NOT NULL DEFAULT '{}',revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,FOREIGN KEY(profile_id) REFERENCES profiles(id));
CREATE TABLE training_sessions(id TEXT PRIMARY KEY,sync_id TEXT NOT NULL UNIQUE,profile_id TEXT NOT NULL,lesson_id TEXT,stage_id TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'normal' CHECK(mode IN('normal','test')),difficulty TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT NOT NULL,duration_ms INTEGER NOT NULL,active_duration_ms INTEGER NOT NULL,char_attempts INTEGER NOT NULL,correct_chars INTEGER NOT NULL,error_count INTEGER NOT NULL,hint_count INTEGER NOT NULL DEFAULT 0,gross_wpm REAL NOT NULL,net_wpm REAL NOT NULL,accuracy REAL NOT NULL,cadence_score REAL,cadence_cv REAL,stall_count INTEGER NOT NULL DEFAULT 0,summary_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,FOREIGN KEY(profile_id) REFERENCES profiles(id));
CREATE INDEX idx_training_sessions_profile_time ON training_sessions(profile_id,started_at DESC);
CREATE TABLE key_mastery(profile_id TEXT NOT NULL,key_code TEXT NOT NULL,display_key TEXT NOT NULL,hand TEXT NOT NULL CHECK(hand IN('left','right','either')),finger TEXT NOT NULL,introduced INTEGER NOT NULL DEFAULT 0 CHECK(introduced IN(0,1)),attempts INTEGER NOT NULL DEFAULT 0,correct INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,total_reaction_ms INTEGER NOT NULL DEFAULT 0,mastery REAL NOT NULL DEFAULT 0,last_practiced TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(profile_id,key_code),FOREIGN KEY(profile_id) REFERENCES profiles(id));
CREATE TABLE generated_content(id TEXT PRIMARY KEY,profile_id TEXT,constraint_hash TEXT NOT NULL,request_mode TEXT NOT NULL,stage_id TEXT NOT NULL,difficulty TEXT NOT NULL,focus_keys_json TEXT NOT NULL DEFAULT '[]',topic TEXT,text TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,prompt_version TEXT NOT NULL,validation_json TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT,completed_count INTEGER NOT NULL DEFAULT 0,rating INTEGER,FOREIGN KEY(profile_id) REFERENCES profiles(id));
CREATE INDEX idx_generated_content_constraint ON generated_content(constraint_hash,created_at DESC);
CREATE TABLE ai_usage(id TEXT PRIMARY KEY,profile_id TEXT,route TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,status TEXT NOT NULL,cached INTEGER NOT NULL DEFAULT 0 CHECK(cached IN(0,1)),input_tokens INTEGER,output_tokens INTEGER,latency_ms INTEGER,created_at TEXT NOT NULL,FOREIGN KEY(profile_id) REFERENCES profiles(id));
CREATE TABLE admin_events(id TEXT PRIMARY KEY,action TEXT NOT NULL,target_profile_id TEXT,detail_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,FOREIGN KEY(target_profile_id) REFERENCES profiles(id));
CREATE INDEX idx_admin_events_time ON admin_events(created_at DESC);
